const cache = $workflow.staticData;
const now = Date.now();
const fiveMin = 5 * 60 * 1000;

if (cache.accessToken && cache.expiresAt && (cache.expiresAt - now) > fiveMin) {
  return [{ json: { accessToken: cache.accessToken, fromCache: true } }];
}
return [{ json: { needsRefresh: true, fromCache: false } }];

const token = $input.first().json;
$workflow.staticData.accessToken = token.access_token;
$workflow.staticData.expiresAt = Date.now() + (token.expires_in * 1000);
return [{ json: { accessToken: token.access_token, fromCache: false } }];

const msg = $input.first().json;
const headers = msg.payload.headers;
const get = (name) => headers.find(h => h.name.toLowerCase() === name.toLowerCase())?.value || '';

function decodePart(part) {
  if (!part) return '';
  if (part.mimeType === 'text/plain' && part.body?.data) {
    return Buffer.from(part.body.data, 'base64').toString('utf-8');
  }
  if (part.mimeType === 'text/html' && part.body?.data) {
    let html = Buffer.from(part.body.data, 'base64').toString('utf-8');
    return html.replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
               .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
               .replace(/<[^>]+>/g, ' ')
               .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&')
               .replace(/\s+/g, ' ').trim();
  }
  if (part.parts) {
    const plain = part.parts.find(p => p.mimeType === 'text/plain');
    if (plain) return decodePart(plain);
    return decodePart(part.parts[0]);
  }
  return '';
}

const body = decodePart(msg.payload).slice(0, 2000);

return [{
  json: {
    message_id: msg.id,
    thread_id: msg.threadId,
    sender: get('From'),
    subject: get('Subject'),
    date: get('Date'),
    body,
    user_id: 'YOUR_USER_ID'
  }
}];

