let parsed;
try {
  parsed = JSON.parse(raw.replace(/```json|```/g, '').trim());
} catch(e) {
  parsed = { skip: true, error: 'parse_failed', raw, category: 'other', urgency_score: 0, tier: 'LOW', summary: '', action: '' };
}
const decoded = $('DecodeEmail').first().json;
return [{ json: { ...parsed, ...decoded } }];

const e = $('ParseAIOutput').first().json;
const tierEmoji = { URGENT: '🔴', MODERATE: '🟡', LOW: '🟢' };
const emoji = tierEmoji[e.tier] || '📧';

let msg = `${emoji} *${e.tier} — ${e.category.replace('_',' ').toUpperCase()}*\n`;
msg += `*From:* ${e.sender}\n`;
msg += `*Subject:* ${e.subject}\n\n`;
msg += `${e.summary}`;
if (e.action) msg += `\n\n✅ *Action:* ${e.action}`;

return [{ json: { message: msg, record_id: $('SaveEmailRecord').first().json.id } }];

const emails = Array.isArray($input.first().json) ? $input.first().json : ($input.first().json.data || []);

const stats = {
  total: emails.length,
  urgent: emails.filter(e => e.tier === 'URGENT').length,
  moderate: emails.filter(e => e.tier === 'MODERATE').length,
  low: emails.filter(e => e.tier === 'LOW').length,
  skipped: emails.filter(e => !e.was_notified).length
};

const byCategory = {};
for (const email of emails) {
  const cat = email.category || 'other';
  if (!byCategory[cat]) byCategory[cat] = [];
  byCategory[cat].push({
    subject: email.subject,
    sender: email.sender,
    urgency_score: email.urgency_score,
    summary: email.summary
  });
}

return [{ json: { stats, byCategory, date: new Date().toDateString(), rawCount: emails.length } }];

