const action = $('ParseApprovalOutput').first().json.action;
const draft = $('ParseApprovalOutput').first().json.updatedDraft;

if (action === 'send') {
  return [{ json: { message: `✅ Email sent to ${draft.to}`, intent: 'approval_sent' } }];
}
if (action === 'cancel') {
  return [{ json: { message: '🗑️ Draft cancelled.', intent: 'approval_cancelled' } }];
}
if (action === 'edit') {
  const preview = `✏️ *Updated draft:*\n\n*To:* ${draft.to}\n*Subject:* ${draft.subject}\n\n${(draft.body||'').slice(0,300)}...\n\nReply *yes* to send or *no* to cancel.`;
  return [{ json: { message: preview, intent: 'approval_edit' } }];
}
return [{ json: { message: 'Something went wrong. Please try again.', intent: 'error' } }];

