const draftData = hasDraft ? (toolCalls.find(t => t.name === 'COMPOSE_EMAIL' || t.function?.name === 'COMPOSE_EMAIL')) : null;

return [{ json: { ...output, hasDraft, draftData } }];

const hasDraft = $('IsDraftOutput').first().json.hasDraft;
